CREATE TABLE IF NOT EXISTS site_chrome_settings (`key` VARCHAR(80) PRIMARY KEY, value TEXT NULL, updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS site_navigation_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, location VARCHAR(40) NOT NULL, label VARCHAR(120) NOT NULL, url VARCHAR(500) NOT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NULL, KEY idx_site_nav (location,is_active,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
